// Generated from openapi.yaml by build-html.ps1. Do not edit.
window.OPENAPI_YAML = "openapi: 3.1.0\ninfo:\n  title: Rukmini Eat API\n  description: |\n    Restaurant discovery, local ordering, and admin APIs. Log in or register to obtain a JWT, then use **Authorize**. Provider integrations (Zomato/Swiggy) are not connected.\n\n    ## Frontend routes\n    The Angular app runs at `http://localhost:4200`. Its routes are screens, not REST endpoints; they call the backend operations below.\n\n    | Frontend route | Screen | Backend operations |\n    |---|---|---|\n    | `/login` | Sign in / create account (guests only) | `POST /api/auth/login`, `POST /api/auth/register` |\n    | `/restaurants` | Dashboard, search, filters, sorting | `GET /api/restaurants` |\n    | `/restaurants/:id` | Restaurant menu | `GET /api/restaurants/{id}` |\n    | `/cart` | Cart and checkout | `POST /api/orders` |\n    | `/orders` | Order history | `GET /api/orders` |\n    | `/` or unknown route | Redirects to `/restaurants` | None |\n\n    All routes except `/login` require sign-in. No frontend screens exist for the administration or provider-integration operations; use this Swagger UI.\n  version: v1\nservers:\n- url: http://localhost:8080/rukmini-eat\n  description: Generated server url\nsecurity:\n- bearerAuth: []\ntags:\n- name: Administration\n  description: Requires a JWT with the ADMIN role.\npaths:\n  /api/orders:\n    get:\n      tags:\n      - Orders\n      summary: \"List the signed-in customer\u0027s orders, newest first\"\n      operationId: history\n      responses:\n        \"200\":\n          description: Orders for the signed-in customer; empty list when none\n          content:\n            \u0027*/*\u0027:\n              schema:\n                type: array\n                items:\n                  $ref: \"#/components/schemas/OrderDto\"\n        \"401\":\n          description: \"Missing, invalid, or expired token\"\n    post:\n      tags:\n      - Orders\n      summary: Place a local order\n      description: Items must belong to one restaurant. Maximum 20 units per item\n        and 50 request lines. Prices and fees are recalculated on the server; orders\n        are not sent to external providers.\n      operationId: place\n      requestBody:\n        content:\n          application/json:\n            schema:\n              $ref: \"#/components/schemas/OrderRequest\"\n        required: true\n      responses:\n        \"201\":\n          description: Order placed with server-calculated totals\n          content:\n            \u0027*/*\u0027:\n              schema:\n                $ref: \"#/components/schemas/OrderDto\"\n        \"400\":\n          description: \"Invalid request, unknown menu item, quantity over 20, or items\\\n            \\ from multiple restaurants\"\n          content:\n            \u0027*/*\u0027:\n              schema:\n                $ref: \"#/components/schemas/ApiError\"\n        \"401\":\n          description: \"Missing, invalid, or expired token\"\n  /api/auth/register:\n    post:\n      tags:\n      - Authentication\n      summary: Create a customer account and return a JWT\n      operationId: register\n      requestBody:\n        content:\n          application/json:\n            schema:\n              $ref: \"#/components/schemas/RegisterRequest\"\n        required: true\n      responses:\n        \"429\":\n          description: Too many attempts from this address; see Retry-After\n          content:\n            \u0027*/*\u0027:\n              schema:\n                $ref: \"#/components/schemas/ApiError\"\n        \"201\":\n          description: Account created; token and user returned\n          content:\n            \u0027*/*\u0027:\n              schema:\n                $ref: \"#/components/schemas/AuthResponse\"\n        \"400\":\n          description: Invalid input\n          content:\n            \u0027*/*\u0027:\n              schema:\n                $ref: \"#/components/schemas/ApiError\"\n        \"409\":\n          description: Email is already registered\n          content:\n            \u0027*/*\u0027:\n              schema:\n                $ref: \"#/components/schemas/ApiError\"\n      security: []\n  /api/auth/login:\n    post:\n      tags:\n      - Authentication\n      summary: Log in and return a JWT\n      operationId: login\n      requestBody:\n        content:\n          application/json:\n            schema:\n              $ref: \"#/components/schemas/LoginRequest\"\n        required: true\n      responses:\n        \"429\":\n          description: Too many attempts from this address; see Retry-After\n          content:\n            \u0027*/*\u0027:\n              schema:\n                $ref: \"#/components/schemas/ApiError\"\n        \"200\":\n          description: Login succeeded; token and user returned\n          content:\n            \u0027*/*\u0027:\n              schema:\n                $ref: \"#/components/schemas/AuthResponse\"\n        \"400\":\n          description: Invalid input\n          content:\n            \u0027*/*\u0027:\n              schema:\n                $ref: \"#/components/schemas/ApiError\"\n        \"401\":\n          description: Invalid email or password\n          content:\n            \u0027*/*\u0027:\n              schema:\n                $ref: \"#/components/schemas/ApiError\"\n      security: []\n  /api/admin/restaurants:\n    post:\n      tags:\n      - Administration\n      summary: Create a restaurant (ADMIN)\n      operationId: create\n      requestBody:\n        content:\n          application/json:\n            schema:\n              $ref: \"#/components/schemas/RestaurantCreateRequest\"\n        required: true\n      responses:\n        \"201\":\n          description: Restaurant created\n          content:\n            \u0027*/*\u0027:\n              schema:\n                $ref: \"#/components/schemas/RestaurantSummary\"\n        \"400\":\n          description: Invalid input\n          content:\n            \u0027*/*\u0027:\n              schema:\n                $ref: \"#/components/schemas/ApiError\"\n        \"401\":\n          description: \"Missing, invalid, or expired token\"\n        \"403\":\n          description: Signed-in user is not an ADMIN\n  /api/admin/restaurants/{id}/menu-items:\n    post:\n      tags:\n      - Administration\n      summary: Add a menu item to a restaurant (ADMIN)\n      operationId: addMenuItem\n      parameters:\n      - name: id\n        in: path\n        required: true\n        schema:\n          type: integer\n          format: int64\n      requestBody:\n        content:\n          application/json:\n            schema:\n              $ref: \"#/components/schemas/MenuItemCreateRequest\"\n        required: true\n      responses:\n        \"201\":\n          description: Menu item added\n          content:\n            \u0027*/*\u0027:\n              schema:\n                $ref: \"#/components/schemas/MenuItemDto\"\n        \"400\":\n          description: Invalid input\n          content:\n            \u0027*/*\u0027:\n              schema:\n                $ref: \"#/components/schemas/ApiError\"\n        \"401\":\n          description: \"Missing, invalid, or expired token\"\n        \"403\":\n          description: Signed-in user is not an ADMIN\n        \"404\":\n          description: Restaurant not found\n          content:\n            \u0027*/*\u0027:\n              schema:\n                $ref: \"#/components/schemas/ApiError\"\n  /api/restaurants:\n    get:\n      tags:\n      - Restaurants\n      summary: Search and filter restaurants\n      operationId: list\n      parameters:\n      - name: q\n        in: query\n        description: \"Search restaurant names, cuisines, or menu item names\"\n        required: false\n        schema:\n          type: string\n      - name: cuisine\n        in: query\n        description: \"Cuisine substring, case-insensitive\"\n        required: false\n        schema:\n          type: string\n      - name: vegOnly\n        in: query\n        required: false\n        schema:\n          type: boolean\n          default: false\n      - name: topRated\n        in: query\n        description: Only restaurants rated at least 4.3\n        required: false\n        schema:\n          type: boolean\n          default: false\n      - name: fast\n        in: query\n        description: Only restaurants with an ETA of 25 minutes or less\n        required: false\n        schema:\n          type: boolean\n          default: false\n      - name: sort\n        in: query\n        required: false\n        schema:\n          type: string\n          default: relevance\n          enum:\n          - relevance\n          - rating\n          - eta\n          - costLow\n          - costHigh\n      responses:\n        \"200\":\n          description: Matching restaurants; empty list when none match\n          content:\n            \u0027*/*\u0027:\n              schema:\n                type: array\n                items:\n                  $ref: \"#/components/schemas/RestaurantSummary\"\n        \"401\":\n          description: \"Missing, invalid, or expired token\"\n  /api/restaurants/{id}:\n    get:\n      tags:\n      - Restaurants\n      summary: Get a restaurant and its menu\n      operationId: get\n      parameters:\n      - name: id\n        in: path\n        required: true\n        schema:\n          type: integer\n          format: int64\n      responses:\n        \"200\":\n          description: Restaurant with menu items\n          content:\n            \u0027*/*\u0027:\n              schema:\n                $ref: \"#/components/schemas/RestaurantDetail\"\n        \"401\":\n          description: \"Missing, invalid, or expired token\"\n        \"404\":\n          description: Restaurant not found\n          content:\n            \u0027*/*\u0027:\n              schema:\n                $ref: \"#/components/schemas/ApiError\"\n  /api/integrations/providers:\n    get:\n      tags:\n      - Provider integrations\n      summary: Get provider integration readiness\n      description: \"Static implementation status, not a provider health check. Live\\\n        \\ data and real ordering remain disabled.\"\n      operationId: providers\n      responses:\n        \"200\":\n          description: Zomato and Swiggy readiness status\n          content:\n            \u0027*/*\u0027:\n              schema:\n                type: array\n                items:\n                  $ref: \"#/components/schemas/ProviderStatus\"\n        \"401\":\n          description: \"Missing, invalid, or expired token\"\ncomponents:\n  schemas:\n    OrderLineRequest:\n      type: object\n      properties:\n        menuItemId:\n          type: integer\n          format: int64\n          example: 1\n        quantity:\n          type: integer\n          format: int32\n          example: 2\n          maximum: 20\n          minimum: 1\n      required:\n      - menuItemId\n    OrderRequest:\n      type: object\n      properties:\n        items:\n          type: array\n          items:\n            $ref: \"#/components/schemas/OrderLineRequest\"\n          maxItems: 50\n          minItems: 0\n      required:\n      - items\n    ApiError:\n      type: object\n      description: Application validation or business error\n      properties:\n        message:\n          type: string\n          example: Invalid email or password\n    OrderDto:\n      type: object\n      properties:\n        id:\n          type: integer\n          format: int64\n        restaurantName:\n          type: string\n        status:\n          type: string\n        items:\n          type: array\n          items:\n            $ref: \"#/components/schemas/OrderLineDto\"\n        subtotal:\n          type: number\n        deliveryFee:\n          type: number\n        tax:\n          type: number\n        platformFee:\n          type: number\n        total:\n          type: number\n        createdAt:\n          type: string\n          format: date-time\n    OrderLineDto:\n      type: object\n      properties:\n        name:\n          type: string\n        price:\n          type: number\n        quantity:\n          type: integer\n          format: int32\n    RegisterRequest:\n      type: object\n      properties:\n        name:\n          type: string\n          example: Asha Rao\n          maxLength: 80\n          minLength: 0\n        email:\n          type: string\n          format: email\n          example: asha@example.com\n          maxLength: 160\n          minLength: 0\n        password:\n          type: string\n          example: Secret@123\n          maxLength: 72\n          minLength: 6\n      required:\n      - email\n      - name\n      - password\n    AuthResponse:\n      type: object\n      properties:\n        token:\n          type: string\n        user:\n          $ref: \"#/components/schemas/UserDto\"\n    UserDto:\n      type: object\n      properties:\n        id:\n          type: integer\n          format: int64\n        name:\n          type: string\n        email:\n          type: string\n        role:\n          type: string\n    LoginRequest:\n      type: object\n      properties:\n        email:\n          type: string\n          example: demo@rukmini.com\n          minLength: 1\n        password:\n          type: string\n          example: Demo@123\n          minLength: 1\n      required:\n      - email\n      - password\n    RestaurantCreateRequest:\n      type: object\n      properties:\n        name:\n          type: string\n          example: Masala House\n          maxLength: 120\n          minLength: 0\n        cuisines:\n          type: string\n          description: Comma-separated cuisines\n          example: \"North Indian, Tandoor\"\n          maxLength: 200\n          minLength: 0\n        rating:\n          type: number\n          example: 4.5\n          maximum: 5.0\n          minimum: 0.0\n        etaMinutes:\n          type: integer\n          format: int32\n          example: 30\n          maximum: 180\n          minimum: 5\n        costForTwo:\n          type: integer\n          format: int32\n          example: 500\n          minimum: 0\n        pureVeg:\n          type: boolean\n        emoji:\n          type: string\n          maxLength: 8\n          minLength: 0\n        description:\n          type: string\n          maxLength: 300\n          minLength: 0\n      required:\n      - cuisines\n      - name\n      - rating\n    RestaurantSummary:\n      type: object\n      properties:\n        id:\n          type: integer\n          format: int64\n        name:\n          type: string\n        cuisines:\n          type: array\n          items:\n            type: string\n        rating:\n          type: number\n          format: double\n        etaMinutes:\n          type: integer\n          format: int32\n        costForTwo:\n          type: integer\n          format: int32\n        pureVeg:\n          type: boolean\n        emoji:\n          type: string\n        description:\n          type: string\n    MenuItemCreateRequest:\n      type: object\n      properties:\n        name:\n          type: string\n          example: Paneer Tikka\n          maxLength: 120\n          minLength: 0\n        category:\n          type: string\n          example: Starters\n          maxLength: 60\n          minLength: 0\n        price:\n          type: number\n          example: 249.0\n          minimum: 1.0\n        veg:\n          type: boolean\n        bestseller:\n          type: boolean\n        emoji:\n          type: string\n          maxLength: 8\n          minLength: 0\n      required:\n      - category\n      - name\n      - price\n    MenuItemDto:\n      type: object\n      properties:\n        id:\n          type: integer\n          format: int64\n        name:\n          type: string\n        category:\n          type: string\n        price:\n          type: number\n        veg:\n          type: boolean\n        bestseller:\n          type: boolean\n        emoji:\n          type: string\n    RestaurantDetail:\n      type: object\n      properties:\n        id:\n          type: integer\n          format: int64\n        name:\n          type: string\n        cuisines:\n          type: array\n          items:\n            type: string\n        rating:\n          type: number\n          format: double\n        etaMinutes:\n          type: integer\n          format: int32\n        costForTwo:\n          type: integer\n          format: int32\n        pureVeg:\n          type: boolean\n        emoji:\n          type: string\n        description:\n          type: string\n        menu:\n          type: array\n          items:\n            $ref: \"#/components/schemas/MenuItemDto\"\n    ProviderStatus:\n      type: object\n      properties:\n        provider:\n          type: string\n        status:\n          type: string\n        liveData:\n          type: boolean\n        realOrdering:\n          type: boolean\n  securitySchemes:\n    bearerAuth:\n      type: http\n      scheme: bearer\n      bearerFormat: JWT\n";
